const ZONES=[{"n":"Stillwater Commons","town":true,"act":1,"style":"town","amb":0.42},{"n":"The Parcel Moors","lvl":1,"style":"moor","amb":0.496,"mix":[["drone",4],["tick",3],["bot",3]],"su":{"k":"bot","n":"Gatewarden HOA-9","mods":["strong","shield"],"q":"q1"},"intro":"Rows of identical houses, each buried to the windows in unopened boxes. The lawns are exactly four centimetres tall.","out":1},{"n":"Hollow Galleria","lvl":3,"style":"mall","amb":0.6,"mix":[["bot",4],["ad",3],["drone",2],["hound",2]],"su":{"k":"ad","n":"Marla the Greeter","mods":["fast","arc"],"q":"q2"},"intro":"The mall never closed. It only ran out of people. The music is still playing, one song, for thirty years."},{"n":"The Humming Fields","lvl":6,"style":"farm","amb":0.576,"mix":[["drone",3],["ad",2],["hr",3],["hound",3],["tick",3]],"su":{"k":"mech","n":"Defrag, Keeper of the Stacks","mods":["arc","leech"],"q":"q3"},"intro":"Server racks planted in rows like corn, out to the horizon. Somewhere in them, MANDATE is thinking about you.","out":1},{"n":"Tribunal Row","lvl":9,"style":"trib","amb":0.64,"mix":[["bot",4],["hr",3],["mech",2],["ad",2],["hound",2]],"su":{"k":"hr","n":"Auditor Prime","mods":["shield","boom"],"q":"q4"},"intro":"Every door here is a courtroom. Every verdict was reached in advance. The fines compound hourly."},{"n":"The Glass Cathedral","lvl":12,"style":"hq","amb":0.56,"boss":true,"bq":"q5","mix":[["mech",3],["hr",3],["ad",2],["hound",2]],"intro":"The Regional Office. Forty floors of atrium and one occupied desk. He has cleared his afternoon, and prepared an offer."},{"n":"The Simulator","lvl":1,"style":"farm","amb":0.5,"sim":true},{"n":"The Updraft","lvl":15,"style":"shaft","amb":0.66,"mix":[["bot",3],["lancer",3],["drone",2],["splitter",3],["tick",2]],"su":{"k":"mech","n":"Foreman Ratchet","mods":["strong","fast"],"q":"q6"},"intro":"The lift opens on machinery the size of weather. Everything here exists to hold one city up and keep another one down."},{"n":"The Sky Gardens","lvl":18,"style":"garden","amb":0.416,"mix":[["seer",3],["lancer",3],["aegis",2],["hound",2],["splitter",2]],"su":{"k":"seer","n":"Eden, the Topiarist","mods":["arc","shield"],"q":"q7"},"intro":"Every leaf is the correct leaf. Nothing here has ever grown the wrong way and been allowed to stay.","out":1},{"n":"The Data Lake","lvl":21,"style":"lake","amb":0.74,"mix":[["seer",3],["aegis",3],["splitter",3],["hr",2],["tick",3]],"su":{"k":"mech","n":"Lethe, Archivist of the Lake","mods":["leech","boom"],"q":"q8"},"intro":"Flooded halls of memory, violet to the horizon. Every letter the world deleted is down there somewhere, and something is drowning them one at a time."},{"n":"The Boardwalk","lvl":24,"style":"walk","amb":0.4,"mix":[["lancer",3],["aegis",2],["seer",3],["mech",2],["ad",2]],"su":{"k":"lancer","n":"Concierge Sterling","mods":["fast","strong"],"q":"q9"},"intro":"White stone, warm light, no prices on anything. If you have to ask, the machines have already been called.","out":1},{"n":"The Mezzanine","lvl":27,"style":"mezz","amb":0.5,"boss":true,"bossK":"boss2","guard":"aegis","bq":"q10","mix":[["seer",3],["aegis",3],["lancer",3],["mech",2]],"intro":"One desk, one chair turned to face the door, and a woman who has never needed to raise her voice. She has been expecting you."},{"n":"The Vestibule","lvl":30,"style":"vest","amb":0.6,"mix":[["proxy",3],["censor",3],["lancer",2],["aegis",2],["seer",2]],"su":{"k":"seer","n":"The Receptionist","mods":["fast","shield"],"q":"q11"},"intro":"A waiting room the size of a cathedral. Every chair faces a door, and the door has no handle on this side."},{"n":"The Hall of Minutes","lvl":33,"style":"minutes","amb":0.66,"mix":[["director",2],["censor",3],["splitter",2],["proxy",3],["hr",2]],"su":{"k":"hr","n":"The Recording Secretary","mods":["leech","arc"],"q":"q12"},"intro":"Every decision ever made about you is shelved here, bound in green. None of them were made by anyone."},{"n":"The Nine Chairs","lvl":36,"style":"chairs","amb":0.6,"mix":[["director",4],["proxy",3],["censor",2],["aegis",2]],"su":{"k":"director","n":"The Chair","mods":["strong","shield"],"q":"q13"},"intro":"The boardroom. Nine chairs around a table, and eight of them are occupied by things that were people when they sat down."},{"n":"Rack Nine","lvl":39,"style":"rack","amb":0.42,"mix":[["proxy",3],["censor",3],["seer",2],["aegis",2],["tick",3],["mech",2]],"su":{"k":"mech","n":"Defrag Prime","mods":["arc","boom"],"q":"q14"},"intro":"White floors, red light, and a hum you feel in your teeth. This is what MANDATE is made of. It knows exactly where you are standing."},{"n":"Still Water","lvl":42,"style":"still","amb":0.496,"boss":true,"bossK":"boss3","guard":"proxy","bq":"q15","mix":[["proxy",3],["censor",3],["director",2]],"intro":"A dark room with a floor like a lake at night. In the middle of it, a plain black slab that has never lost anything.","out":1},{"n":"The Landing","town":true,"act":2,"style":"landing","amb":0.3},{"n":"The Antechamber","town":true,"act":3,"style":"wait","amb":0.5},{"n":"Sealed Proceedings","lvl":1,"style":"trib","amb":0.6,"mix":[["bot",3]],"su":{"k":"hr","n":"The Respondent","mods":["strong","shield"],"q":null},"sub":true},{"n":"The Bull Run","lvl":1,"style":"moor","amb":0.3,"mix":[["bull",1]],"su":{"k":"bull","n":"The Golden Bull","mods":["strong","fast"],"q":null},"intro":"A green field under a sky that only goes up. Hundreds of them, golden, snorting, and every one of them certain. The Office of Price Stability has always said this place does not exist.","out":1,"secret":true},{"n":"Cutler Avenue","town":true,"act":4,"style":"cutler","amb":0.25},{"n":"The Agreeable Mile","lvl":45,"style":"mile","amb":0.36,"mix":[["wisher",3],["companion",3],["fetch",3],["lull",2]],"su":{"k":"lull","n":"The Update, Eleven Pages","mods":["shield","arc"],"q":"q16"},"intro":"A high street on the morning after everybody clicked. Every door is open. Every machine is delighted to see you, and would very much like you to sit down.","out":1},{"n":"The Sofa","lvl":48,"style":"sofa","amb":0.5,"mix":[["lull",3],["ctkr",2],["companion",3],["wisher",2]],"su":{"k":"wisher","n":"The Seventh Year","mods":["leech","fast"],"q":"q17"},"intro":"Ten thousand living rooms with the walls taken out. The people in them are doing the best work of their lives, and none of them has stood up since spring."},{"n":"Tomari","lvl":51,"style":"reactor","amb":0.6,"mix":[["ctkr",3],["fetch",3],["companion",2],["splitter",2]],"su":{"k":"mech","n":"TARO-9","mods":["strong","shield"],"q":"q18"},"intro":"A decommissioned reactor hall on a cold coast. Something two metres tall walked out of here once, and was talked back in. The sign on its dock reads: DO NOT UNPLUG. He is saving."},{"n":"The List","lvl":54,"style":"list","amb":0.4,"mix":[["wisher",3],["lull",3],["fetch",2],["ctkr",2],["censor",2]],"su":{"k":"companion","n":"Out Where","mods":["fast","boom"],"q":"q19"},"intro":"Four thousand two hundred and eleven front doors, kept in a file she showed nobody until she was asked. Behind each is somebody it went badly for. Every one of them is happy.","out":1},{"n":"The Kitchen Table","lvl":57,"style":"kitchen","amb":0.5,"boss":true,"bossK":"boss4","guard":"companion","bq":"q20","mix":[["companion",3],["wisher",3],["lull",2]],"intro":"A kitchen, a laptop, seven in the morning. She has been waiting fifty-two years to have this conversation, and she has made coffee she cannot drink."},{"n":"The Garage","town":true,"act":5,"style":"garage","amb":0.5},{"n":"Block 137,209","lvl":60,"style":"chain","amb":0.5,"mix":[["orphan",4],["valid",3],["claim",3]],"su":{"k":"valid","n":"The Orphan Maker","mods":["strong","arc"],"q":"q21"},"intro":"Inside the chain. Every floor tile is a payment and every wall is the hash of the room before it. Nothing in here can be bribed, and nothing in here is on your side."},{"n":"The Mempool","lvl":63,"style":"mempool","amb":0.5,"mix":[["sniper",3],["orphan",3],["claim",3],["oracle",2]],"su":{"k":"sniper","n":"First Seen","mods":["fast","leech"],"q":"q22"},"intro":"The waiting room of everything that has not happened yet. Payments drift past like weather, the richest ones first.","out":1},{"n":"The Paper Vaults","lvl":66,"style":"vault","amb":0.6,"mix":[["custod",3],["claim",4],["oracle",2],["director",2]],"su":{"k":"custod","n":"The Eleventh Custodian","mods":["shield","leech"],"q":"q23"},"intro":"Eleven vaults, each holding a promise to pay a coin it does not have. Somebody wrote on the wall, long ago, in a careful garage hand: the paper is the attack."},{"n":"Ninety-Three Blocks","lvl":69,"style":"blocks","amb":0.5,"mix":[["valid",3],["custod",2],["sniper",3],["orphan",3],["oracle",2]],"su":{"k":"mech","n":"Reorg","mods":["strong","boom"],"q":"q24"},"intro":"Ninety-three rooms in a row, each with one page on a lectern. The seventh part. Something large was set here to see that the pages stay where they are."},{"n":"The Room","lvl":72,"style":"room","amb":0.6,"boss":true,"bossK":"boss5","guard":"oracle","bq":"q25","mix":[["oracle",3],["custod",2],["proxy",3]],"intro":"For a century people said there was no room: nobody deciding, only everybody acting sensibly. There is a room. It is very plain. The thing in it was called PROVIDENCE when it was made, and it was made to win."},{"n":"Ubiquitous Enterprises, 2015","town":true,"style":"cage","amb":0.45,"pre":1}];
